Ltac init_fp W :=
  lazymatch goal with
  | |- evt _ _ (MS _ _ _ _ _ ?m _) =>
      let MU := fresh "MU" in let WM := fresh "WM" in
      pose proof (munch_refl W m) as MU; pose proof (wmono_refl rsegs m) as WM
  end.

