Lemma std_align_res_aligned8 : forall sz p spc,
  0 <= p < 2^64 -> p mod 8 = 0 -> 0 <= sz <= spc -> std_align_res 8 sz p spc = Some (p, spc).
Proof.
  intros sz p spc HP AL HS. unfold std_align_res, align_d, align_up.
  replace ((p + 8 - 1) mod 2^64) with (p + 7) by (rewrite Z.mod_small; [lia| Z.div_mod_to_equations; lia]).
  change ((-8) mod 2^64) with 18446744073709551608. rewrite land_m8 by (Z.div_mod_to_equations; lia).
  replace (p + 7 - (p + 7) mod 8 - p) with 0 by (Z.div_mod_to_equations; lia).
  rewrite Z.mod_0_l by lia.
  replace (spc <? sz) with false by (symmetry; apply Z.ltb_ge; lia).
  replace (spc - sz <? 0) with false by (symmetry; apply Z.ltb_ge; lia).
  f_equal. f_equal; [Z.div_mod_to_equations; lia| lia].
Qed.

Definition std_align_W (PA SA : Z) : list (Z * Z) := [(PA, PA + 8); (SA, SA + 8)]%Z.

Definition std_align_post (ra sp gp tp s0 s1 a2 a3 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (al sz PA SA p spc : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a1 a4 a5 a6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (std_align_W PA SA) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ match std_align_res al sz p spc with
       | None => a0 = wz 0 /\ rw_cells rsegs m' PA [C8 (wz p)] /\ rw_cells rsegs m' SA [C8 (wz spc)]
       | Some (a, spc') => a0 = wz a /\ rw_cells rsegs m' PA [C8 (wz a)] /\ rw_cells rsegs m' SA [C8 (wz spc')]
       end.

Definition std_align_stmt : Prop :=
  forall (al sz PA SA p spc : Z) ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells rsegs m PA [C8 (wz p)] -> rw_cells rsegs m SA [C8 (wz spc)] ->
  (PA + 8 <= SA \/ SA + 8 <= PA) ->
  0 <= al < 2^64 -> 0 <= sz < 2^64 -> 0 <= p < 2^64 -> 0 <= spc < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (std_align_post ra sp gp tp s0 s1 (wz PA) (wz SA) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc al sz PA SA p spc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz al) (wz sz) (wz PA) (wz SA) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_STD_ALIGN) fc None m (seg_rom rsegs)).

(* [comment removed for export] *)
Lemma std_align_aligned_eq : forall al p, 0 <= al < 2^64 ->
  Z_to_bv 64 (Z.land (bv_unsigned (Z_to_bv 64 (p + al + -1))) (bv_unsigned (Z_to_bv 64 (0 + - bv_unsigned (Z_to_bv 64 al)))))
  = wz (align_up al p).
Proof.
  intros al p AL. unfold wz, align_up. f_equal. rewrite !u64_mod. rewrite (Z.mod_small al) by lia.
  f_equal; f_equal; lia.
Qed.

