(* [comment removed for export] *)
Lemma strcmp_lit : forall (L R : Z) (nl nr : nat) (v : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ro_bytes_b rsegs L (lit_bytes L nl) = true -> ro_bytes_b rsegs R (lit_bytes R nr) = true ->
  0 <= L -> L + Z.of_nat (length (lit_bytes L nl)) <= 2^64 -> 0 <= R -> R + Z.of_nat (length (lit_bytes R nr)) <= 2^64 ->
  has_nul (lit_bytes L nl) = true -> has_nul (lit_bytes R nr) = true ->
  strcmp_val (lit_bytes L nl) (lit_bytes R nr) = v ->
  mem_inv rsegs m ->
  evt rsegs (strcmp_post ra sp gp tp s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc v m)
